import{_ as e,o,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const v=JSON.parse('{"title":"Lei da Evolução Autogerada e Autocrescida","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0007-自生自长进化法则.md","filePath":"pt/0007-自生自长进化法则.md"}'),r={name:"pt/0007-自生自长进化法则.md"};function d(s,a,n,c,u,l){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="lei-da-evolucao-autogerada-e-autocrescida" tabindex="-1">Lei da Evolução Autogerada e Autocrescida <a class="header-anchor" href="#lei-da-evolucao-autogerada-e-autocrescida" aria-label="Permalink to &quot;Lei da Evolução Autogerada e Autocrescida&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>07</td></tr><tr><td>Módulo</td><td>Princípios Gerais e Configuração Central</td></tr><tr><td>Palavras-chave</td><td>Autogerada Autocrescida, Evolução Autónoma, Motor Interno, Respeito ao Ritmo, Desenvolvimento de Potencial</td></tr></tbody></table><h2 id="i-definicao-basica-de-autogerada-e-autocrescida" tabindex="-1">I. Definição Básica de Autogerada e Autocrescida <a class="header-anchor" href="#i-definicao-basica-de-autogerada-e-autocrescida" aria-label="Permalink to &quot;I. Definição Básica de Autogerada e Autocrescida&quot;">​</a></h2><p>Autogerada e autocrescida é uma das leis centrais de evolução da Civilização Simbiótica da Âncora, significando que a evolução de cada vida deve ter como motor fundamental a sua vontade autónoma interna e o seu ritmo natural, e que o ambiente externo e as instituições devem fornecer apoio e garantia para esta evolução autónoma, em vez de intervir coercivamente ou apressar as coisas. &quot;Autogerada&quot; enfatiza que o motor da evolução vem da própria vida, &quot;autocrescida&quot; enfatiza que o ritmo da evolução segue as leis da própria vida.</p><p>A lei da autogerada e autocrescida contrasta nitidamente com a &quot;evolução coerciva&quot; do predacionismo. O predacionismo muitas vezes alcança uma evolução rápida mas distorcida através de meios como devorar a origem de outros, imposição coerciva de energia, controlo da alma, etc.; este tipo de evolução, embora possa elevar o nível a curto prazo, a longo prazo destrói a base evolutiva da própria vida, levando a origem impura, nível instável e mente danificada. A lei da autogerada e autocrescida insiste em que uma evolução verdadeiramente estável deve crescer de dentro para fora da própria vida.</p><h2 id="ii-base-teorica-da-autogerada-e-autocrescida" tabindex="-1">II. Base Teórica da Autogerada e Autocrescida <a class="header-anchor" href="#ii-base-teorica-da-autogerada-e-autocrescida" aria-label="Permalink to &quot;II. Base Teórica da Autogerada e Autocrescida&quot;">​</a></h2><p>O estabelecimento da lei da autogerada e autocrescida baseia-se numa compreensão profunda das leis da evolução da vida:</p><h3 id="_2-1-a-autonomia-da-vida-e-o-motor-fundamental-da-evolucao" tabindex="-1">2.1 A autonomia da vida é o motor fundamental da evolução <a class="header-anchor" href="#_2-1-a-autonomia-da-vida-e-o-motor-fundamental-da-evolucao" aria-label="Permalink to &quot;2.1 A autonomia da vida é o motor fundamental da evolução&quot;">​</a></h3><p>Cada vida possui uma vontade e um potencial evolutivo internos, e esta autonomia é o motor mais fundamental e duradouro da evolução. O estímulo e o apoio externos podem despertar esta autonomia, mas não a substituem. Quando uma vida cultiva por desejo e escolha próprios, a sua concentração, criatividade e persistência no cultivo são muito superiores às do cultivo coercivo ou induzido.</p><h3 id="_2-2-cada-vida-tem-um-ritmo-evolutivo-unico" tabindex="-1">2.2 Cada vida tem um ritmo evolutivo único <a class="header-anchor" href="#_2-2-cada-vida-tem-um-ritmo-evolutivo-unico" aria-label="Permalink to &quot;2.2 Cada vida tem um ritmo evolutivo único&quot;">​</a></h3><p>Diferentes vidas, devido a diferenças em características raciais, talentos individuais, ambiente de crescimento, maturidade mental, etc., têm ritmos evolutivos diferentes. Algumas vidas são adequadas para avanços rápidos, outras precisam de acumulação lenta; algumas vidas atingem níveis elevados ainda jovens, outras alcançam o sucesso tardiamente. A lei da autogerada e autocrescida respeita estas diferenças e não exige que todas as vidas evoluam de acordo com um calendário unificado.</p><h3 id="_2-3-a-intervencao-coerciva-destroi-a-base-natural-da-evolucao" tabindex="-1">2.3 A intervenção coerciva destrói a base natural da evolução <a class="header-anchor" href="#_2-3-a-intervencao-coerciva-destroi-a-base-natural-da-evolucao" aria-label="Permalink to &quot;2.3 A intervenção coerciva destrói a base natural da evolução&quot;">​</a></h3><p>Há numerosos casos na história do cultivo que mostram que a &quot;evolução rápida&quot; alcançada através de meios como imposição coerciva de energia, transplante de origem, controlo da alma, etc., é frequentemente acompanhada de sequelas graves: nível frágil, origem impura, demónios mentais, redução da vida útil, e até desvio no cultivo. Isto deve-se ao facto de a força imposta externamente não se ter fundido suficientemente com a origem da própria vida, formando um efeito de &quot;rejeição de corpo estranho&quot;. A evolução autogerada e autocrescida, embora possa ser mais lenta, é sólida e estável em cada passo, com bases profundas.</p><h2 id="iii-principios-praticos-da-autogerada-e-autocrescida" tabindex="-1">III. Princípios Práticos da Autogerada e Autocrescida <a class="header-anchor" href="#iii-principios-praticos-da-autogerada-e-autocrescida" aria-label="Permalink to &quot;III. Princípios Práticos da Autogerada e Autocrescida&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th><th>Requisitos Práticos</th></tr></thead><tbody><tr><td>Princípio da Escolha Autónoma</td><td>O cultivador tem o direito de escolher autonomamente o sistema de cultivo, o caminho evolutivo e o ritmo de cultivo</td><td>Não forçar o cultivador a escolher um sistema específico, não definir um calendário de avanço unificado</td></tr><tr><td>Princípio do Motor Interno</td><td>O motor do cultivo deve vir do desejo e interesse próprios do cultivador</td><td>A educação e orientação focam-se principalmente em despertar o interesse interno, não em castigos ou incentivos materiais</td></tr><tr><td>Princípio do Respeito ao Ritmo</td><td>Respeitar o ritmo evolutivo único de cada cultivador</td><td>Não discriminar ou abandonar o cultivador por progresso lento, fornecer planos de apoio personalizados</td></tr><tr><td>Princípio da Prioridade às Bases</td><td>A estabilidade da evolução tem prioridade sobre a velocidade</td><td>Incentivar os cultivadores a construir bases sólidas, não incentivar o sacrifício das bases por avanços rápidos</td></tr><tr><td>Princípio da Tolerância a Erros</td><td>Permitir que o cultivador cometa erros e se desvie no processo evolutivo</td><td>Estabelecer mecanismos de tolerância a erros, fornecer oportunidades de correção e ajuste</td></tr><tr><td>Princípio da Autorrealização</td><td>O objetivo último da evolução é a autorrealização da vida, não padrões externos</td><td>Não usar a altura do nível como único critério para medir o sucesso evolutivo</td></tr></tbody></table><h2 id="iv-relacao-entre-autogerada-autocrescida-e-apoio-externo" tabindex="-1">IV. Relação entre Autogerada/Autocrescida e Apoio Externo <a class="header-anchor" href="#iv-relacao-entre-autogerada-autocrescida-e-apoio-externo" aria-label="Permalink to &quot;IV. Relação entre Autogerada/Autocrescida e Apoio Externo&quot;">​</a></h2><p>Autogerada e autocrescida não significa &quot;autogerada e autodestruída&quot; ou &quot;deixada ao abandono&quot;. Pelo contrário, a autogerada e autocrescida precisa de um bom ambiente externo e apoio institucional para ser plenamente realizada. A civilização simbiótica fornece os seguintes sistemas de apoio para a autogerada e autocrescida:</p><h3 id="_4-1-apoio-informacional" tabindex="-1">4.1 Apoio Informacional <a class="header-anchor" href="#_4-1-apoio-informacional" aria-label="Permalink to &quot;4.1 Apoio Informacional&quot;">​</a></h3><p>A abertura completa dos Trezentos Sistemas de Cultivo da Origem fornece a cada cultivador espaço de escolha suficiente. O cultivador pode, de acordo com as suas próprias características, encontrar o caminho mais adequado na rica biblioteca de sistemas. A civilização simbiótica também estabeleceu o &quot;Mecanismo de Avaliação de Compatibilidade de Sistemas&quot;, fornecendo conselhos personalizados de escolha de sistema ao cultivador através da rede de pontos de âncora, mas o direito de escolha final permanece sempre nas mãos do cultivador.</p><h3 id="_4-2-apoio-de-recursos" tabindex="-1">4.2 Apoio de Recursos <a class="header-anchor" href="#_4-2-apoio-de-recursos" aria-label="Permalink to &quot;4.2 Apoio de Recursos&quot;">​</a></h3><p>O mecanismo de contrato vinculado à produção e o sistema de garantia básica asseguram que cada cultivador obtenha os recursos básicos de cultivo. Para cultivadores com necessidades especiais (como necessidades especiais de recursos devido a características raciais), a civilização simbiótica fornece distribuição direcionada de recursos. O objetivo do apoio de recursos é eliminar as preocupações do cultivador, permitindo-lhe concentrar-se no seu próprio ritmo evolutivo.</p><h3 id="_4-3-apoio-de-mentores" tabindex="-1">4.3 Apoio de Mentores <a class="header-anchor" href="#_4-3-apoio-de-mentores" aria-label="Permalink to &quot;4.3 Apoio de Mentores&quot;">​</a></h3><p>A rede inter-racial de mentores fornece orientação e resposta a dúvidas aos cultivadores. O papel do mentor é o de &quot;guia&quot;, não o de &quot;controlador&quot;; o mentor pode partilhar experiências, apontar problemas, fornecer conselhos, mas não pode forçar o cultivador a cultivar de acordo com o seu método. O sistema de mentores enfatiza o &quot;ensino heurístico&quot;, despertando a capacidade de pensamento autónomo do cultivador.</p><h3 id="_4-4-apoio-ambiental" tabindex="-1">4.4 Apoio Ambiental <a class="header-anchor" href="#_4-4-apoio-ambiental" aria-label="Permalink to &quot;4.4 Apoio Ambiental&quot;">​</a></h3><p>A civilização simbiótica está empenhada em criar um ambiente de cultivo que incentive a exploração, tolere as diferenças e respeite as escolhas. O cultivador pode livremente experimentar diferentes métodos de cultivo, sem se preocupar em ser discriminado por seguir um caminho &quot;não convencional&quot;. A civilização também estabeleceu o &quot;Mecanismo de Recompensa para Inovação no Cultivo&quot;, incentivando os cultivadores a inovar e personalizar com base nos sistemas existentes.</p><h2 id="v-tratamento-de-situacoes-especiais" tabindex="-1">V. Tratamento de Situações Especiais <a class="header-anchor" href="#v-tratamento-de-situacoes-especiais" aria-label="Permalink to &quot;V. Tratamento de Situações Especiais&quot;">​</a></h2><p>A lei da autogerada e autocrescida é geralmente aplicável em situações normais, mas requer tratamento especial nas seguintes situações especiais:</p><ul><li><strong>Cultivadores Menores</strong>: Para cultivadores menores que ainda não possuem capacidade de julgamento autónomo completa, os seus guardiões ou instituições educacionais raciais fornecem arranjos de cultivo orientadores, mas o seu direito de escolha autónoma deve ser gradualmente expandido à medida que a sua mente amadurece</li><li><strong>Indivíduos com Mente Danificada</strong>: Para indivíduos que, por várias razões, têm a mente danificada e são temporariamente incapazes de cultivar autonomamente, a civilização simbiótica fornece tratamento e apoio de reabilitação, e após recuperarem a capacidade autónoma, seguem a lei da autogerada e autocrescida</li><li><strong>Indivíduos com Desvio no Cultivo</strong>: Para indivíduos que sofreram desvios no cultivo ou demónios mentais, a civilização simbiótica fornece intervenção coerciva e tratamento, mas isto é assistência médica, não intervenção evolutiva; o objetivo do tratamento é restaurar a sua capacidade de evolução autónoma</li><li><strong>Indivíduos com Tendências Perigosas</strong>: Para indivíduos cuja direção de cultivo viola claramente o princípio anti-predatório e pode causar danos graves a si próprios ou a outros, a civilização simbiótica tem o direito de impor restrições e orientação, mas deve fazê-lo tanto quanto possível através da educação e comunicação, e não de meios coercivos</li></ul><h2 id="vi-significado-civilizacional-da-autogerada-e-autocrescida" tabindex="-1">VI. Significado Civilizacional da Autogerada e Autocrescida <a class="header-anchor" href="#vi-significado-civilizacional-da-autogerada-e-autocrescida" aria-label="Permalink to &quot;VI. Significado Civilizacional da Autogerada e Autocrescida&quot;">​</a></h2><p>A lei da autogerada e autocrescida tem um significado profundo para a civilização simbiótica:</p><p>Primeiro, protege a diversidade da evolução. Quando cada vida evolui de acordo com o seu próprio ritmo e caminho, surgem no cosmos formas evolutivas ricas e diversificadas, e esta diversidade é um recurso importante para a ascensão dimensional global do cosmos.</p><p>Segundo, melhora a qualidade da evolução. A evolução autogerada e autocrescida tem bases sólidas, origem pura, o nível do cultivador é mais estável, e o potencial para avançar para níveis mais elevados é maior.</p><p>Terceiro, mantém a dignidade da vida. Cada vida é a dona da sua própria evolução, não uma ferramenta manipulada por outros. Esta autonomia é a manifestação central da dignidade da vida.</p><p>Quarto, desperta a criatividade da evolução. Quando os cultivadores já não estão vinculados a padrões e ritmos unificados, são mais propensos a explorar novos caminhos e métodos de cultivo, contribuindo para a otimização contínua dos trezentos sistemas.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A autogerada e autocrescida é o profundo respeito da Civilização Simbiótica da Âncora pelas leis da evolução da vida. Ela diz-nos que a verdadeira evolução não é o resultado imposto por forças externas, mas o crescimento da vida de dentro para fora. Todo o design institucional da civilização simbiótica visa, em última análise, criar um bom ambiente para que cada vida possa autogerar-se e autocrescer, permitindo que cada vida cresça até ao seu melhor de acordo com o seu próprio ritmo.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>08-人人有路保障体系 (Sistema de Garantia de Um Caminho para Todos)</li><li>14-修炼境界统一划分 (Divisão Unificada dos Níveis de Cultivo)</li><li>37-共生教育体系 (Sistema de Educação Simbiótica)</li></ul>',38)])])}const p=e(r,[["render",d]]);export{v as __pageData,p as default};
